-- CA_0362: restore 19 draft Season 3 gun-policy reasoning texts garbled by a research-text trim.
--
-- Stage 5 step 7 (2026-11-04) ran a batch tool, rung3_text.py, that swaps the old rung 3 wording for the revision 5
-- words in the research text. On 19 rows its pattern matched from the closing quote of one passage to the opening
-- quote of the next and replaced everything between them (a vote, a date, the licence-rule sentence) with the rung
-- text, e.g. `...during an emergency"Add limits on buying, ... in hospitals"Add limits on buying...`. The rows were
-- written (pa-01, ma-01) and approved. Found while preparing the held follow-up batch pa-02-held (Matzie, never
-- written). Each new text is the coder's pre-trim text with the other trims kept (quote splits, store-id
-- respellings); four rows (McClinton, Harris, Sappey, Davis) also had the coder's own quote slip around the old
-- rung words, cleaned to the revision 5 words.
--
-- Rows (19): Dan Frankel, Jay Costa, Chris Pielli, Emily Kinkead, Joseph C. Hohenstein, Jennifer O'Mara, David M. Delloso, Maureen E. Madden, Joe Webster, Danielle Friel Otten, Kyle J. Mullins, Joanna E. McClinton, Jordan A. Harris, Christina D. Sappey, Tina M. Davis, Nick Pisciottano, Robert E. Merski, Kathleen C. Tomlinson, Nicholas A. Boldyga.
-- Every seat is rung 3 and does not change. Reasoning text only; value, sources and review rows unchanged.
-- The old text of every row is recorded below (the guard), so the previous values stay readable.
-- Guarded on the exact old text: idempotent, and it refuses a row someone has since edited.
-- Built by .planning/research/s3-prep-gun-policy/stage5/write/garble-fix/repair.py (local research folder).

BEGIN;

CREATE TEMP TABLE ca0362_fix (politician_id uuid PRIMARY KEY, old_text text NOT NULL, new_text text NOT NULL) ON COMMIT DROP;
INSERT INTO ca0362_fix (politician_id, old_text, new_text) VALUES
    ('0a39dc88-89dc-4136-b936-7fad079e50ee'::uuid, 'Co-sponsor and Yea on House final passage, 2023-05-22 (102-99, gate none), of HB 1018 (2023, PN 1152; single-subject) creates extreme risk protection orders: "A court order prohibiting a person from having in the person''s possession or control, purchasing or receiving" … "a firearm, based upon a finding that the person presents a substantial risk of suicide or of causing the death of, or serious bodily injury to, another person"; and co-sponsor of HB 1075 (2019-2020, as filed; single-subject) adds the same kind of order: the court "shall issue an extreme risk protection order" on clear and convincing evidence of a substantial risk, requiring "the relinquishment of all firearms"Add limits on buying, having or carrying a gun, such as checking every buyer, red-flag orders, waiting periods or bans on guns in hospitals"assault rifles" name no law); his ghost-gun, storage and lost-or-stolen bills are restriction side with no rung, and his No votes are on the loosening bills.', 'Co-sponsor and Yea on House final passage, 2023-05-22 (102-99, gate none), of HB 1018 (2023, PN 1152; single-subject) creates extreme risk protection orders: "A court order prohibiting a person from having in the person''s possession or control, purchasing or receiving" … "a firearm, based upon a finding that the person presents a substantial risk of suicide or of causing the death of, or serious bodily injury to, another person"; and co-sponsor of HB 1075 (2019-2020, as filed; single-subject) adds the same kind of order: the court "shall issue an extreme risk protection order" on clear and convincing evidence of a substantial risk, requiring "the relinquishment of all firearms". This is a court order that takes guns from a person found dangerous, the rung''s named act on who may have a gun (Limit who may have a gun). No record of his states a type ban (his own words on "assault rifles" name no law); his ghost-gun, storage and lost-or-stolen bills are restriction side with no rung, and his No votes are on the loosening bills.'),
    ('18000caa-76dd-4b8b-ba7d-1e6d786222ac'::uuid, 'Co-sponsor (2023, in-term, Senate) of SB 204 (2023-2024, as filed; single-subject) provides extreme risk protection orders: on issuance "the court shall order the respondent to surrender to the local law enforcement agency all firearms in the respondent''s custody, control or possession"Add limits on buying, having or carrying a gun, such as checking every buyer, red-flag orders, waiting periods or bans on guns in hospitals"We must prohibit ownership of assault weapons such as the AR-15" (a rung 2 statement), but the page is undated and not a 2026 campaign page, so it cannot support a seat (V5 undated); his dated 2022 words name red flag laws and broader background checks, the same rung.', 'Co-sponsor (2023, in-term, Senate) of SB 204 (2023-2024, as filed; single-subject) provides extreme risk protection orders: on issuance "the court shall order the respondent to surrender to the local law enforcement agency all firearms in the respondent''s custody, control or possession". This is a court order that takes guns from a person found dangerous, the rung''s named act on who may have a gun (Limit who may have a gun). His official-site priorities page says "We must prohibit ownership of assault weapons such as the AR-15" (a rung 2 statement), but the page is undated and not a 2026 campaign page, so it cannot support a seat (V5 undated); his dated 2022 words name red flag laws and broader background checks, the same rung.'),
    ('3ea03f3c-bcaa-4568-87bf-92b8ef333ccf'::uuid, 'The Yea on PA HB 1018 (2023-2024) final passage (102-99, single-subject, census gate none) enacts "a court order prohibiting a person from having in the person''s possession or control, purchasing or receiving" … "a firearm, based upon a finding that the person presents a substantial risk of suicide or of causing the death of, or serious bodily injury to, another person."Add limits on buying, having or carrying a gun, such as checking every buyer, red-flag orders, waiting periods or bans on guns in hospitals"I am proud to have co-sponsored and voted in support of these gun safety bills" (2023), and as a 2022 nominee called for "more extensive comprehensive background checks". His other bills (unserialised-frame rules, a polling-place carry ban, safe storage) reach no rung further than 3.', 'The Yea on PA HB 1018 (2023-2024) final passage (102-99, single-subject, census gate none) enacts "a court order prohibiting a person from having in the person''s possession or control, purchasing or receiving" … "a firearm, based upon a finding that the person presents a substantial risk of suicide or of causing the death of, or serious bodily injury to, another person." That meets ''Limit who may have a gun, such as'' … ''by court orders that take guns from a person found dangerous''. He also co-sponsored HB 1018, says "I am proud to have co-sponsored and voted in support of these gun safety bills" (2023), and as a 2022 nominee called for "more extensive comprehensive background checks". His other bills (unserialised-frame rules, a polling-place carry ban, safe storage) reach no rung further than 3.'),
    ('46f9ef45-e45d-405d-b8bb-2b68b33dbb15'::uuid, 'The Yea on PA HB 1018 (2023-2024) final passage (102-99, single-subject, census gate none) enacts "a court order prohibiting a person from having in the person''s possession or control, purchasing or receiving" … "a firearm, based upon a finding that the person presents a substantial risk of suicide or of causing the death of, or serious bodily injury to, another person."Add limits on buying, having or carrying a gun, such as checking every buyer, red-flag orders, waiting periods or bans on guns in hospitals"We can actually get guns out of the hands of people who should not and cannot be trusted to have firearms" … court orders Her other bills reach no further rung (the handgun-purchase-limit bill HB 837 has no instrument file and is not used).', 'The Yea on PA HB 1018 (2023-2024) final passage (102-99, single-subject, census gate none) enacts "a court order prohibiting a person from having in the person''s possession or control, purchasing or receiving" … "a firearm, based upon a finding that the person presents a substantial risk of suicide or of causing the death of, or serious bodily injury to, another person." That meets ''Limit who may have a gun, such as'' … ''by court orders that take guns from a person found dangerous''. She also co-sponsored HB 1018 and said in 2022: "We can actually get guns out of the hands of people who should not and cannot be trusted to have firearms" … court orders Her other bills reach no further rung (the handgun-purchase-limit bill HB 837 has no instrument file and is not used).'),
    ('7de7f516-ae01-4859-9187-9916da9a8804'::uuid, 'Yea on final passage of PA HB 1018 (2023-05-22). PA HB 1018 (2023-24) is single-subject (Season 3 verdict) and its operative text adds 18 Pa.C.S. 6105(c)(11), barring "A person who is the subject of an active extreme risk protection order", and 42 Pa.C.S. 64A02, "A court order prohibiting a person from having in the person''s possession or control, purchasing or receiving" … "a firearm, based upon a finding that the person presents a substantial risk of suicide or of causing the death of, or serious bodily injury to, another person."Add limits on buying, having or carrying a gun, such as checking every buyer, red-flag orders, waiting periods or bans on guns in hospitals"The court shall issue an extreme risk protection order" … "if the court finds by clear and convincing evidence that the respondent presents a substantial risk"), rung 3. His other records are on the same side and state no further rung act: No votes on SB 565, HB 1747, HB 2440 and HB 979 (direction-only), a Yea on HB 777 (unserialised-frame rules, annex Q6 direction-only), and co-sponsorships of storage, theft-reporting, polling-place and unserialised-gun bills (adjacent or direction-only). His 2022-2023 statements back the same rung but are outside the current election cycle, so the seat rests on the record.', 'Yea on final passage of PA HB 1018 (2023-05-22). PA HB 1018 (2023-24) is single-subject (Season 3 verdict) and its operative text adds 18 Pa.C.S. 6105(c)(11), barring "A person who is the subject of an active extreme risk protection order", and 42 Pa.C.S. 64A02, "A court order prohibiting a person from having in the person''s possession or control, purchasing or receiving" … "a firearm, based upon a finding that the person presents a substantial risk of suicide or of causing the death of, or serious bodily injury to, another person." That is the rung ''Limit who may have a gun, such as'' … ''by court orders that take guns from a person found dangerous''. The House final passage was 102-99 (census gate: none). He also co-sponsored PA HB 1075 (2019-20), whose operative text creates the same extreme risk protection order ("The court shall issue an extreme risk protection order" … "if the court finds by clear and convincing evidence that the respondent presents a substantial risk"), rung 3. His other records are on the same side and state no further rung act: No votes on SB 565, HB 1747, HB 2440 and HB 979 (direction-only), a Yea on HB 777 (unserialised-frame rules, annex Q6 direction-only), and co-sponsorships of storage, theft-reporting, polling-place and unserialised-gun bills (adjacent or direction-only). His 2022-2023 statements back the same rung but are outside the current election cycle, so the seat rests on the record.'),
    ('aa43eae9-aea7-4811-99ea-8395fcfb1af0'::uuid, 'Prime sponsor of HB 1018 (2023-24) and Yea on its House final passage (2023-05-22, 102-99, census gate none). PA HB 1018 (2023-24) adds 42 Pa.C.S. 64A02, an "Extreme risk protection order": "A court order prohibiting a person from having in the person''s possession or control, purchasing or receiving" … "a firearm, based upon a finding that the person presents a substantial risk of suicide or of causing the death of, or serious bodily injury to, another person"Add limits on buying, having or carrying a gun, such as checking every buyer, red-flag orders, waiting periods or bans on guns in hospitals"My bill would allow family members or law enforcement to ask a judge to temporarily disarm someone who is in crisis and who is a threat to themselves or others." (HB 1859 has no instrument file, so it rests only as her words.) She also co-sponsored HB 1075 (2019-20, the same orders, rung 3). Other records stay on the restriction side: HB 777 and HB 1065 (annex Q6), HB 980 (lost-or-stolen report), HB 2244 (storage, adjacent), No votes on SB 565, HB 2440, HB 1747, HB 979. No rung 2 record: furthest act rung 3.', 'Prime sponsor of HB 1018 (2023-24) and Yea on its House final passage (2023-05-22, 102-99, census gate none). PA HB 1018 (2023-24) adds 42 Pa.C.S. 64A02, an "Extreme risk protection order": "A court order prohibiting a person from having in the person''s possession or control, purchasing or receiving" … "a firearm, based upon a finding that the person presents a substantial risk of suicide or of causing the death of, or serious bodily injury to, another person", with relinquishment of firearms within 24 hours (64A12(a)). That is a court order that takes guns from a person found dangerous, the rung 3 act (limit who may have a gun). The store''s single-subject verdict is single (season 3, codebook 0.6). Her own words in her 2026-10-02 newsletter (in-term) state the same act: "My bill would allow family members or law enforcement to ask a judge to temporarily disarm someone who is in crisis and who is a threat to themselves or others." (HB 1859 has no instrument file, so it rests only as her words.) She also co-sponsored HB 1075 (2019-20, the same orders, rung 3). Other records stay on the restriction side: HB 777 and HB 1065 (annex Q6), HB 980 (lost-or-stolen report), HB 2244 (storage, adjacent), No votes on SB 565, HB 2440, HB 1747, HB 979. No rung 2 record: furthest act rung 3.'),
    ('afcee82f-b50d-4c2f-bab2-0f5cd31b1234'::uuid, 'Co-sponsor of HB 1018 (2023-24) and Yea on its House final passage (2023-05-22, 102-99, census gate none). PA HB 1018 (2023-24) adds 42 Pa.C.S. 64A02, an "Extreme risk protection order": "A court order prohibiting a person from having in the person''s possession or control, purchasing or receiving" … "a firearm, based upon a finding that the person presents a substantial risk of suicide or of causing the death of, or serious bodily injury to, another person"Add limits on buying, having or carrying a gun, such as checking every buyer, red-flag orders, waiting periods or bans on guns in hospitals"if the court finds by clear and convincing evidence that the respondent presents a substantial risk"; 64A12(a), relinquishment of all firearms): rung 3. Other records stay on the restriction side: HB 777 and HB 1065 (annex Q6), HB 980 (lost-or-stolen report); No on SB 565, HB 2440, HB 1747, HB 979. His police firearms training bill has no instrument id and is adjacent. No rung 2 record: furthest act rung 3.', 'Co-sponsor of HB 1018 (2023-24) and Yea on its House final passage (2023-05-22, 102-99, census gate none). PA HB 1018 (2023-24) adds 42 Pa.C.S. 64A02, an "Extreme risk protection order": "A court order prohibiting a person from having in the person''s possession or control, purchasing or receiving" … "a firearm, based upon a finding that the person presents a substantial risk of suicide or of causing the death of, or serious bodily injury to, another person", with relinquishment of firearms within 24 hours (64A12(a)). That is a court order that takes guns from a person found dangerous, the rung 3 act (limit who may have a gun). The store''s single-subject verdict is single (season 3, codebook 0.6). He also co-sponsored HB 1075 (2019-20): PA HB 1075 (2019-20) creates the same extreme risk protection orders (64A09(a), "if the court finds by clear and convincing evidence that the respondent presents a substantial risk"; 64A12(a), relinquishment of all firearms): rung 3. Other records stay on the restriction side: HB 777 and HB 1065 (annex Q6), HB 980 (lost-or-stolen report); No on SB 565, HB 2440, HB 1747, HB 979. His police firearms training bill has no instrument id and is adjacent. No rung 2 record: furthest act rung 3.'),
    ('b55531ce-16fd-4932-aa29-c8d3b17cea37'::uuid, 'Yea on PA HB 1018 (2023) House final passage, 2023-05-22, tally 102-99 (single-subject, gate none). It creates an extreme risk protection order, "A court order prohibiting a person from having in the person''s possession or control, purchasing or receiving" … "a firearm, based upon a finding that the person presents a substantial risk of suicide or of causing the death of, or serious bodily injury to, another person."Add limits on buying, having or carrying a gun, such as checking every buyer, red-flag orders, waiting periods or bans on guns in hospitals"The court shall issue an extreme risk protection order" … "if the court finds by clear and convincing evidence that the respondent presents a substantial risk"), rung 3. No record states a rung 2 type ban or a rung 1 act, so the furthest act is rung 3. Other on-topic records (No votes on loosening bills, unserialized-gun and storage bills, preemption) show the same side or are adjacent and do not move the seat.', 'Yea on PA HB 1018 (2023) House final passage, 2023-05-22, tally 102-99 (single-subject, gate none). It creates an extreme risk protection order, "A court order prohibiting a person from having in the person''s possession or control, purchasing or receiving" … "a firearm, based upon a finding that the person presents a substantial risk of suicide or of causing the death of, or serious bodily injury to, another person." A court order that takes guns from a person found dangerous meets rung 3 (limit who may have a gun). Co-sponsor of the same bill, HB 1018 (2023). Also co-sponsor of PA HB 1075 (2019, as filed; single-subject), the same red-flag order ("The court shall issue an extreme risk protection order" … "if the court finds by clear and convincing evidence that the respondent presents a substantial risk"), rung 3. No record states a rung 2 type ban or a rung 1 act, so the furthest act is rung 3. Other on-topic records (No votes on loosening bills, unserialized-gun and storage bills, preemption) show the same side or are adjacent and do not move the seat.'),
    ('b951b2df-73fc-45b5-b423-fc4540038709'::uuid, 'Yea on PA HB 1018 (2023) House final passage, 2023-05-22, tally 102-99 (single-subject, gate none). It creates an extreme risk protection order, "A court order prohibiting a person from having in the person''s possession or control, purchasing or receiving" … "a firearm, based upon a finding that the person presents a substantial risk of suicide or of causing the death of, or serious bodily injury to, another person."Add limits on buying, having or carrying a gun, such as checking every buyer, red-flag orders, waiting periods or bans on guns in hospitals"The court shall issue an extreme risk protection order" … "if the court finds by clear and convincing evidence that the respondent presents a substantial risk"), rung 3. No record states a rung 2 type ban or a rung 1 act, so the furthest act is rung 3. Other on-topic records (No votes on loosening bills, unserialized-gun and storage bills, preemption) show the same side or are adjacent and do not move the seat.', 'Yea on PA HB 1018 (2023) House final passage, 2023-05-22, tally 102-99 (single-subject, gate none). It creates an extreme risk protection order, "A court order prohibiting a person from having in the person''s possession or control, purchasing or receiving" … "a firearm, based upon a finding that the person presents a substantial risk of suicide or of causing the death of, or serious bodily injury to, another person." A court order that takes guns from a person found dangerous meets rung 3 (limit who may have a gun). Co-sponsor of the same bill, HB 1018 (2023). Also co-sponsor of PA HB 1075 (2019, as filed; single-subject), the same red-flag order ("The court shall issue an extreme risk protection order" … "if the court finds by clear and convincing evidence that the respondent presents a substantial risk"), rung 3. No record states a rung 2 type ban or a rung 1 act, so the furthest act is rung 3. Other on-topic records (No votes on loosening bills, unserialized-gun and storage bills, preemption) show the same side or are adjacent and do not move the seat.'),
    ('b98b2079-80c7-4a41-9a80-344ed7f3e19c'::uuid, 'Yea on PA HB 1018 (2023) House final passage, 2023-05-22, tally 102-99 (single-subject, gate none). It creates an extreme risk protection order, "A court order prohibiting a person from having in the person''s possession or control, purchasing or receiving" … "a firearm, based upon a finding that the person presents a substantial risk of suicide or of causing the death of, or serious bodily injury to, another person."Add limits on buying, having or carrying a gun, such as checking every buyer, red-flag orders, waiting periods or bans on guns in hospitals"The court shall issue an extreme risk protection order" … "if the court finds by clear and convincing evidence that the respondent presents a substantial risk"), rung 3. No record states a rung 2 type ban or a rung 1 act, so the furthest act is rung 3. Other on-topic records (No votes on loosening bills, unserialized-gun and storage bills, preemption) show the same side or are adjacent and do not move the seat.', 'Yea on PA HB 1018 (2023) House final passage, 2023-05-22, tally 102-99 (single-subject, gate none). It creates an extreme risk protection order, "A court order prohibiting a person from having in the person''s possession or control, purchasing or receiving" … "a firearm, based upon a finding that the person presents a substantial risk of suicide or of causing the death of, or serious bodily injury to, another person." A court order that takes guns from a person found dangerous meets rung 3 (limit who may have a gun). Co-sponsor of the same bill, HB 1018 (2023). Also co-sponsor of PA HB 1075 (2019, as filed; single-subject), the same red-flag order ("The court shall issue an extreme risk protection order" … "if the court finds by clear and convincing evidence that the respondent presents a substantial risk"), rung 3. No record states a rung 2 type ban or a rung 1 act, so the furthest act is rung 3. Other on-topic records (No votes on loosening bills, unserialized-gun and storage bills, preemption) show the same side or are adjacent and do not move the seat.'),
    ('cb44222f-7bcd-4bff-be2f-fd3d25bc7d79'::uuid, 'Yea on PA HB 1018 (2023) House final passage, 2023-05-22, tally 102-99 (single-subject, gate none). It creates an extreme risk protection order, "A court order prohibiting a person from having in the person''s possession or control, purchasing or receiving" … "a firearm, based upon a finding that the person presents a substantial risk of suicide or of causing the death of, or serious bodily injury to, another person."Add limits on buying, having or carrying a gun, such as checking every buyer, red-flag orders, waiting periods or bans on guns in hospitals"The court shall issue an extreme risk protection order" … "if the court finds by clear and convincing evidence that the respondent presents a substantial risk"), rung 3. No record states a rung 2 type ban or a rung 1 act, so the furthest act is rung 3. Other on-topic records (No votes on loosening bills, unserialized-gun and storage bills, preemption) show the same side or are adjacent and do not move the seat.', 'Yea on PA HB 1018 (2023) House final passage, 2023-05-22, tally 102-99 (single-subject, gate none). It creates an extreme risk protection order, "A court order prohibiting a person from having in the person''s possession or control, purchasing or receiving" … "a firearm, based upon a finding that the person presents a substantial risk of suicide or of causing the death of, or serious bodily injury to, another person." A court order that takes guns from a person found dangerous meets rung 3 (limit who may have a gun). Also co-sponsor of PA HB 1075 (2019, as filed; single-subject), the same red-flag order ("The court shall issue an extreme risk protection order" … "if the court finds by clear and convincing evidence that the respondent presents a substantial risk"), rung 3. No record states a rung 2 type ban or a rung 1 act, so the furthest act is rung 3. Other on-topic records (No votes on loosening bills, unserialized-gun and storage bills, preemption) show the same side or are adjacent and do not move the seat.'),
    ('d85f8be7-dcef-4e91-a754-6a34fcce8c25'::uuid, 'Yea on final passage of PA HB 1018 (2023) creates extreme risk protection orders: "A court order prohibiting a person from having in the person''s possession or control, purchasing or receiving" … "a firearm, based upon a finding that the person presents a substantial risk", with relinquishment "of all firearms owned by the respondent"Add limits on buying, having or carrying a gun, such as checking every buyer, red-flag orders, waiting periods or bans on guns in hospitals" … "by court orders that take guns from a person found dangerous). Single-subject in the store, tally 102-99, census gate none. She also co-sponsored PA HB 1075 (2019), as filed, is the same extreme-risk order bill ("The court shall issue an extreme risk protection order" … "if the court finds by clear and convincing evidence that the respondent presents a substantial risk"; relinquishment of "all firearms"), a rung 3 act. Votes or sponsorships on PA HB 777 (2023) and its 2025 successor (unserialized frames and kits) are direction-only on the restriction side (annex Q6; runner ruling) and do not make the record two-sided. Her co-sponsorships of HB 980 (report lost or stolen guns) and HB 1157 (faster mental-health reporting, annex D2) are not rung acts. Her Nays on SB 565, HB 1747, HB 2440 and HB 979 are No votes and seat nothing; no loosening-side rung act in the findings.', 'Yea on final passage of PA HB 1018 (2023) creates extreme risk protection orders: "A court order prohibiting a person from having in the person''s possession or control, purchasing or receiving" … "a firearm, based upon a finding that the person presents a substantial risk", with relinquishment "of all firearms owned by the respondent" within 24 hours. That meets rung 3, "Add limits on buying, having or carrying a gun, such as checking every buyer, red-flag orders, waiting periods or bans on guns in hospitals" (a red-flag order). Single-subject in the store, tally 102-99, census gate none. She also co-sponsored PA HB 1075 (2019), as filed, is the same extreme-risk order bill ("The court shall issue an extreme risk protection order" … "if the court finds by clear and convincing evidence that the respondent presents a substantial risk"; relinquishment of "all firearms"), a rung 3 act. Votes or sponsorships on PA HB 777 (2023) and its 2025 successor (unserialized frames and kits) are direction-only on the restriction side (annex Q6; runner ruling) and do not make the record two-sided. Her co-sponsorships of HB 980 (report lost or stolen guns) and HB 1157 (faster mental-health reporting, annex D2) are not rung acts. Her Nays on SB 565, HB 1747, HB 2440 and HB 979 are No votes and seat nothing; no loosening-side rung act in the findings.'),
    ('d939419d-8022-47cb-9800-1d2594a027a1'::uuid, 'Yea on final passage of PA HB 1018 (2023) creates extreme risk protection orders: "A court order prohibiting a person from having in the person''s possession or control, purchasing or receiving" … "a firearm, based upon a finding that the person presents a substantial risk", with relinquishment "of all firearms owned by the respondent"Add limits on buying, having or carrying a gun, such as checking every buyer, red-flag orders, waiting periods or bans on guns in hospitals" … "by court orders that take guns from a person found dangerous). Single-subject in the store, tally 102-99, census gate none. He also co-sponsored PA HB 1075 (2019), as filed, is the same extreme-risk order bill ("The court shall issue an extreme risk protection order" … "if the court finds by clear and convincing evidence that the respondent presents a substantial risk"; relinquishment of "all firearms"), a rung 3 act. Votes or sponsorships on PA HB 777 (2023) and its 2025 successor (unserialized frames and kits) are direction-only on the restriction side (annex Q6; runner ruling) and do not make the record two-sided. His co-sponsorship of HB 980 (lost or stolen gun reporting) is not a rung act. His Nays on SB 565, HB 1747, HB 2440 and HB 979 seat nothing; no loosening-side rung act in the findings.', 'Yea on final passage of PA HB 1018 (2023) creates extreme risk protection orders: "A court order prohibiting a person from having in the person''s possession or control, purchasing or receiving" … "a firearm, based upon a finding that the person presents a substantial risk", with relinquishment "of all firearms owned by the respondent" within 24 hours. That meets rung 3, "Add limits on buying, having or carrying a gun, such as checking every buyer, red-flag orders, waiting periods or bans on guns in hospitals" (a red-flag order). Single-subject in the store, tally 102-99, census gate none. He also co-sponsored PA HB 1075 (2019), as filed, is the same extreme-risk order bill ("The court shall issue an extreme risk protection order" … "if the court finds by clear and convincing evidence that the respondent presents a substantial risk"; relinquishment of "all firearms"), a rung 3 act. Votes or sponsorships on PA HB 777 (2023) and its 2025 successor (unserialized frames and kits) are direction-only on the restriction side (annex Q6; runner ruling) and do not make the record two-sided. His co-sponsorship of HB 980 (lost or stolen gun reporting) is not a rung act. His Nays on SB 565, HB 1747, HB 2440 and HB 979 seat nothing; no loosening-side rung act in the findings.'),
    ('d95dc477-aac0-4631-b9fa-5423d8f6edf5'::uuid, 'Co-sponsor of, and Yea on final passage of, PA HB 1018 (2023) creates extreme risk protection orders: "A court order prohibiting a person from having in the person''s possession or control, purchasing or receiving" … "a firearm, based upon a finding that the person presents a substantial risk", with relinquishment "of all firearms owned by the respondent"Add limits on buying, having or carrying a gun, such as checking every buyer, red-flag orders, waiting periods or bans on guns in hospitals" … "by court orders that take guns from a person found dangerous). Single-subject in the store, tally 102-99, census gate none. She also co-sponsored PA HB 1075 (2019), as filed, is the same extreme-risk order bill ("The court shall issue an extreme risk protection order" … "if the court finds by clear and convincing evidence that the respondent presents a substantial risk"; relinquishment of "all firearms"), a rung 3 act. Votes or sponsorships on PA HB 777 (2023) / HB 1065 (2025) (unserialized frames and kits) are direction-only on the restriction side (annex Q6; runner ruling) and do not make the record two-sided. HB 2244 (safe storage and a tax exclusion for gun safes) is adjacent; HB 980 (lost or stolen gun reporting) is not a rung act. Her Nays on SB 565, HB 1747, HB 2440 and HB 979 seat nothing; no loosening-side rung act in the findings.', 'Co-sponsor of, and Yea on final passage of, PA HB 1018 (2023) creates extreme risk protection orders: "A court order prohibiting a person from having in the person''s possession or control, purchasing or receiving" … "a firearm, based upon a finding that the person presents a substantial risk", with relinquishment "of all firearms owned by the respondent" within 24 hours. That meets rung 3, "Add limits on buying, having or carrying a gun, such as checking every buyer, red-flag orders, waiting periods or bans on guns in hospitals" (a red-flag order). Single-subject in the store, tally 102-99, census gate none. She also co-sponsored PA HB 1075 (2019), as filed, is the same extreme-risk order bill ("The court shall issue an extreme risk protection order" … "if the court finds by clear and convincing evidence that the respondent presents a substantial risk"; relinquishment of "all firearms"), a rung 3 act. Votes or sponsorships on PA HB 777 (2023) / HB 1065 (2025) (unserialized frames and kits) are direction-only on the restriction side (annex Q6; runner ruling) and do not make the record two-sided. HB 2244 (safe storage and a tax exclusion for gun safes) is adjacent; HB 980 (lost or stolen gun reporting) is not a rung act. Her Nays on SB 565, HB 1747, HB 2440 and HB 979 seat nothing; no loosening-side rung act in the findings.'),
    ('de144f04-328a-4bf5-8420-dc0321e8b65f'::uuid, 'Co-sponsor of, and Yea on final passage of, PA HB 1018 (2023) creates extreme risk protection orders: "A court order prohibiting a person from having in the person''s possession or control, purchasing or receiving" … "a firearm, based upon a finding that the person presents a substantial risk", with relinquishment "of all firearms owned by the respondent"Add limits on buying, having or carrying a gun, such as checking every buyer, red-flag orders, waiting periods or bans on guns in hospitals" … "by court orders that take guns from a person found dangerous). Single-subject in the store, tally 102-99, census gate none. She also co-sponsored PA HB 1075 (2019), as filed, is the same extreme-risk order bill ("The court shall issue an extreme risk protection order" … "if the court finds by clear and convincing evidence that the respondent presents a substantial risk"; relinquishment of "all firearms"), a rung 3 act. Votes or sponsorships on PA HB 777 (2023) and its 2025 successor (unserialized frames and kits) are direction-only on the restriction side (annex Q6; runner ruling) and do not make the record two-sided. Her Nays on SB 565, HB 1747, HB 2440 and HB 979 seat nothing; no loosening-side rung act in the findings.', 'Co-sponsor of, and Yea on final passage of, PA HB 1018 (2023) creates extreme risk protection orders: "A court order prohibiting a person from having in the person''s possession or control, purchasing or receiving" … "a firearm, based upon a finding that the person presents a substantial risk", with relinquishment "of all firearms owned by the respondent" within 24 hours. That meets rung 3, "Add limits on buying, having or carrying a gun, such as checking every buyer, red-flag orders, waiting periods or bans on guns in hospitals" (a red-flag order). Single-subject in the store, tally 102-99, census gate none. She also co-sponsored PA HB 1075 (2019), as filed, is the same extreme-risk order bill ("The court shall issue an extreme risk protection order" … "if the court finds by clear and convincing evidence that the respondent presents a substantial risk"; relinquishment of "all firearms"), a rung 3 act. Votes or sponsorships on PA HB 777 (2023) and its 2025 successor (unserialized frames and kits) are direction-only on the restriction side (annex Q6; runner ruling) and do not make the record two-sided. Her Nays on SB 565, HB 1747, HB 2440 and HB 979 seat nothing; no loosening-side rung act in the findings.'),
    ('df6fd884-1a0d-4010-87d7-679c0b4ad71d'::uuid, 'HB 1018 (2023) adds 18 Pa.C.S. 6105(c)(11), barring "A person who is the subject of an active extreme risk protection order", and a court order "prohibiting a person from having in the person''s possession or control, purchasing or receiving" (Yea, final passage 2023-05-22, 102-99): a court order that takes guns from a person found dangerous. HB 777 (2023) makes it a felony to sell or transfer "a firearm frame or receiver" … "not imprinted with a serial number registered with a Federal firearms licensee" (Yea, final passage 2024-03-27, 104-97): a ban on selling unserialised frames and receivers (Session C rung 3). He also co-sponsored HB 946 (2021), letting counties "waive the fees" … "for an applicant who is an honorably discharged veteran" … "or is 65 years of age or older"Add limits on buying, having or carrying a gun, such as checking every buyer, red-flag orders, waiting periods or bans on guns in hospitals"Add limits on buying, having or carrying a gun". His No on SB 565 (2021, permitless carry) shows a side only; his No votes on HB 979 (2021) and, in the Senate, SB 822 (2026) are on preemption (adjacent). House and Senate records of one legislature both count (V5).', 'HB 1018 (2023) adds 18 Pa.C.S. 6105(c)(11), barring "A person who is the subject of an active extreme risk protection order", and a court order "prohibiting a person from having in the person''s possession or control, purchasing or receiving" (Yea, final passage 2023-05-22, 102-99): a court order that takes guns from a person found dangerous. HB 777 (2023) makes it a felony to sell or transfer "a firearm frame or receiver" … "not imprinted with a serial number registered with a Federal firearms licensee" (Yea, final passage 2024-03-27, 104-97): a ban on selling unserialised frames and receivers (Session C rung 3). He also co-sponsored HB 946 (2021), letting counties "waive the fees" … "for an applicant who is an honorably discharged veteran" … "or is 65 years of age or older" for a licence to carry: an easier permit, rung 4 under Session C. Under the licence rule (Session C, 2026-11-03) a rung 4 act that keeps the permit does not conflict with rung 3 acts that limit who may have a gun or how guns are made or sold, so the record sits at rung 3, "Add limits on buying, having or carrying a gun". His No on SB 565 (2021, permitless carry) shows a side only; his No votes on HB 979 (2021) and, in the Senate, SB 822 (2026) are on preemption (adjacent). House and Senate records of one legislature both count (V5).'),
    ('e4750674-01e8-49f7-a29a-532c24478bee'::uuid, 'HB 1018 (2023) adds 18 Pa.C.S. 6105(c)(11), barring "A person who is the subject of an active extreme risk protection order", and a court order "prohibiting a person from having in the person''s possession or control, purchasing or receiving" (Yea, final passage 2023-05-22, 102-99): a court order that takes guns from a person found dangerous. HB 777 (2023) makes it a felony to sell or transfer "a firearm frame or receiver" … "not imprinted with a serial number registered with a Federal firearms licensee" (Yea, final passage 2024-03-27, 104-97): a ban on selling unserialised frames and receivers (Session C rung 3). HB 1747 (2019) strikes 6107(a), "No person shall carry a firearm upon the public streets or upon any public property during an emergency"Add limits on buying, having or carrying a gun, such as checking every buyer, red-flag orders, waiting periods or bans on guns in hospitals"Add limits on buying, having or carrying a gun". The No on SB 565 (2021, permitless carry) shows a side only; HB 979 (2021) is preemption and HB 2440 (2019) a rule on gun businesses (adjacent). He also co-sponsored HB 2440 (adjacent).', 'HB 1018 (2023) adds 18 Pa.C.S. 6105(c)(11), barring "A person who is the subject of an active extreme risk protection order", and a court order "prohibiting a person from having in the person''s possession or control, purchasing or receiving" (Yea, final passage 2023-05-22, 102-99): a court order that takes guns from a person found dangerous. HB 777 (2023) makes it a felony to sell or transfer "a firearm frame or receiver" … "not imprinted with a serial number registered with a Federal firearms licensee" (Yea, final passage 2024-03-27, 104-97): a ban on selling unserialised frames and receivers (Session C rung 3). HB 1747 (2019) strikes 6107(a), "No person shall carry a firearm upon the public streets or upon any public property during an emergency" (Yea, final passage 2020-06-24, 127-74), lifting a carry ban during a declared emergency while the licence stays: rung 4. Under the licence rule (Session C, 2026-11-03) a rung 4 act that keeps the permit does not conflict with rung 3 acts that limit who may have a gun or how guns are made or sold, so the record sits at rung 3, "Add limits on buying, having or carrying a gun". The No on SB 565 (2021, permitless carry) shows a side only; HB 979 (2021) is preemption and HB 2440 (2019) a rule on gun businesses (adjacent). He also co-sponsored HB 2440 (adjacent).'),
    ('e96f1aeb-b347-438c-8214-df74a5f62721'::uuid, 'HB 1018 (2023) adds 18 Pa.C.S. 6105(c)(11), barring "A person who is the subject of an active extreme risk protection order", and a court order "prohibiting a person from having in the person''s possession or control, purchasing or receiving" (Yea, final passage 2023-05-22, 102-99): a court order that takes guns from a person found dangerous. HB 777 (2023) makes it a felony to sell or transfer "a firearm frame or receiver" … "not imprinted with a serial number registered with a Federal firearms licensee" (Yea, final passage 2024-03-27, 104-97): a ban on selling unserialised frames and receivers (Session C rung 3). HB 1747 (2019) strikes 6107(a), "No person shall carry a firearm upon the public streets or upon any public property during an emergency"Add limits on buying, having or carrying a gun, such as checking every buyer, red-flag orders, waiting periods or bans on guns in hospitals"Add limits on buying, having or carrying a gun". The No on SB 565 (2021, permitless carry) shows a side only; HB 979 (2021) is preemption and HB 2440 (2019) a rule on gun businesses (adjacent). Her own words that "Every new gun purchaser completes a criminal background check, and the same should be true for private transactions" match rung 3 too, but they are undated, so they cannot support the seat (V5) and are not cited. HB 1592 has no instrument file in the store; HB 2026 (school detection technology) and HB 596 (prosecution task force) are adjacent.', 'HB 1018 (2023) adds 18 Pa.C.S. 6105(c)(11), barring "A person who is the subject of an active extreme risk protection order", and a court order "prohibiting a person from having in the person''s possession or control, purchasing or receiving" (Yea, final passage 2023-05-22, 102-99): a court order that takes guns from a person found dangerous. HB 777 (2023) makes it a felony to sell or transfer "a firearm frame or receiver" … "not imprinted with a serial number registered with a Federal firearms licensee" (Yea, final passage 2024-03-27, 104-97): a ban on selling unserialised frames and receivers (Session C rung 3). HB 1747 (2019) strikes 6107(a), "No person shall carry a firearm upon the public streets or upon any public property during an emergency" (Yea, final passage 2020-06-24, 127-74), lifting a carry ban during a declared emergency while the licence stays: rung 4. Under the licence rule (Session C, 2026-11-03) a rung 4 act that keeps the permit does not conflict with rung 3 acts that limit who may have a gun or how guns are made or sold, so the record sits at rung 3, "Add limits on buying, having or carrying a gun". The No on SB 565 (2021, permitless carry) shows a side only; HB 979 (2021) is preemption and HB 2440 (2019) a rule on gun businesses (adjacent). Her own words that "Every new gun purchaser completes a criminal background check, and the same should be true for private transactions" match rung 3 too, but they are undated, so they cannot support the seat (V5) and are not cited. HB 1592 has no instrument file in the store; HB 2026 (school detection technology) and HB 596 (prosecution task force) are adjacent.'),
    ('541efc37-b332-4c80-8264-7b655efed5ac'::uuid, 'Yea on H 4670 (2017), the 2018 House conference report (Roll Call 389, 133-15, no gate; single-subject), whose operative text adds extreme risk protection orders: on a finding that "the respondent poses a risk of causing bodily injury to self or others" the court "shall order the respondent to surrender any licenses to carry firearms, firearms identification cards and all firearms"Add limits on buying, having or carrying a gun, such as checking every buyer, red-flag orders, waiting periods or bans on guns in hospitals"unequivocally opposed to this anti-Second Amendment attack") show the loosening side only (direction-only, annex Q2): they are not rung acts, so the record is not two-sided, and a No on a different bill does not cancel the Yea (runner ruling). His Yea on H 4517 (2017) is near-unanimous.', 'Yea on H 4670 (2017), the 2018 House conference report (Roll Call 389, 133-15, no gate; single-subject), whose operative text adds extreme risk protection orders: on a finding that "the respondent poses a risk of causing bodily injury to self or others" the court "shall order the respondent to surrender any licenses to carry firearms, firearms identification cards and all firearms". That is a court order that takes guns from a person found dangerous, the rung ''Limit who may have a gun''. (Its stun-gun storage line is adjacent.) His Nays on MA-H-4376-2013, MA-H-4139-2023 and MA-H-4885-2024 (multi-subject) and his own words against the 2023 bill ("unequivocally opposed to this anti-Second Amendment attack") show the loosening side only (direction-only, annex Q2): they are not rung acts, so the record is not two-sided, and a No on a different bill does not cancel the Yea (runner ruling). His Yea on H 4517 (2017) is near-unanimous.');

DO $$
DECLARE n int;
BEGIN
  SELECT count(*) INTO n FROM inform.politician_context c JOIN ca0362_fix f ON f.politician_id = c.politician_id
   WHERE c.season_id = '7b3a066c-815d-43b2-a6a0-6a3029778075' AND c.topic_id = '56125933-b82a-46c5-847b-b2e9a146b89f' AND c.reasoning IN (f.old_text, f.new_text);
  IF n <> 19 THEN RAISE EXCEPTION 'pre-flight: expected 19 rows holding the old or new text, found %', n; END IF;
END $$;

UPDATE inform.politician_context c SET reasoning = f.new_text, updated_at = now()
  FROM ca0362_fix f
 WHERE c.politician_id = f.politician_id AND c.season_id = '7b3a066c-815d-43b2-a6a0-6a3029778075' AND c.topic_id = '56125933-b82a-46c5-847b-b2e9a146b89f' AND c.reasoning = f.old_text;

DO $$
DECLARE n int; v int;
BEGIN
  SELECT count(*) INTO n FROM inform.politician_context c JOIN ca0362_fix f ON f.politician_id = c.politician_id
   WHERE c.season_id = '7b3a066c-815d-43b2-a6a0-6a3029778075' AND c.topic_id = '56125933-b82a-46c5-847b-b2e9a146b89f' AND c.reasoning = f.new_text;
  IF n <> 19 THEN RAISE EXCEPTION 'post-verify: expected 19 corrected rows, found %', n; END IF;
  SELECT count(*) INTO v FROM inform.politician_answers a JOIN ca0362_fix f ON f.politician_id = a.politician_id
   WHERE a.season_id = '7b3a066c-815d-43b2-a6a0-6a3029778075' AND a.topic_id = '56125933-b82a-46c5-847b-b2e9a146b89f' AND a.value = 3;
  IF v <> 19 THEN RAISE EXCEPTION 'post-verify: a seat moved (expected 19 at rung 3), found %', v; END IF;
  SELECT count(*) INTO n FROM inform.politician_context c
   WHERE c.season_id = '7b3a066c-815d-43b2-a6a0-6a3029778075' AND c.topic_id = '56125933-b82a-46c5-847b-b2e9a146b89f' AND c.reasoning ~ '[^[:space:](]"Add limits on buying';
  IF n <> 0 THEN RAISE EXCEPTION 'post-verify: % gun-policy draft rows still carry glued rung text', n; END IF;
END $$;

COMMIT;
